mapper.select:
SELECT invoice_id, booking_id, shipper_id, shipper_name, shipper_type, contract_number, base_amount, discount_amount, adjustment_amount, tax_amount, total_amount, currency, discount_rate, billing_status, calculated_at, projected_at, last_event_id FROM invoice
AND billing_status NOT IN ('PAID', 'VOID')
AND booking_id = #{bookingId}
ORDER BY calculated_at DESC, invoice_id LIMIT #{limit}
